-- Attendance Pattern Analyzer - MySQL 8 schema
-- Generated by backend/gen_schema.py from the SQLAlchemy models.
-- Usage:  mysql -u root -p < schema.sql

CREATE DATABASE IF NOT EXISTS attendance_ai CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE attendance_ai;


CREATE TABLE users (
	id INTEGER NOT NULL AUTO_INCREMENT, 
	`role` ENUM('mentor','teacher','student') NOT NULL, 
	name VARCHAR(120) NOT NULL, 
	email VARCHAR(190), 
	usn VARCHAR(30), 
	password_hash VARCHAR(255) NOT NULL, 
	is_active BOOL NOT NULL, 
	created_at DATETIME NOT NULL DEFAULT now(), 
	PRIMARY KEY (id), 
	UNIQUE (email), 
	UNIQUE (usn)
);


CREATE TABLE mentors (
	id INTEGER NOT NULL AUTO_INCREMENT, 
	user_id INTEGER NOT NULL, 
	department VARCHAR(100), 
	PRIMARY KEY (id), 
	UNIQUE (user_id), 
	FOREIGN KEY(user_id) REFERENCES users (id) ON DELETE CASCADE
);


CREATE TABLE teachers (
	id INTEGER NOT NULL AUTO_INCREMENT, 
	user_id INTEGER NOT NULL, 
	department VARCHAR(100), 
	PRIMARY KEY (id), 
	UNIQUE (user_id), 
	FOREIGN KEY(user_id) REFERENCES users (id) ON DELETE CASCADE
);


CREATE TABLE classes (
	id INTEGER NOT NULL AUTO_INCREMENT, 
	mentor_id INTEGER NOT NULL, 
	name VARCHAR(100) NOT NULL, 
	branch VARCHAR(60) NOT NULL, 
	semester INTEGER NOT NULL, 
	section VARCHAR(10), 
	academic_year VARCHAR(15) NOT NULL, 
	created_at DATETIME NOT NULL DEFAULT now(), 
	PRIMARY KEY (id), 
	FOREIGN KEY(mentor_id) REFERENCES mentors (id) ON DELETE CASCADE
);

CREATE INDEX ix_classes_mentor_id ON classes (mentor_id);

CREATE TABLE students (
	id INTEGER NOT NULL AUTO_INCREMENT, 
	user_id INTEGER, 
	class_id INTEGER NOT NULL, 
	name VARCHAR(120) NOT NULL, 
	usn VARCHAR(30) NOT NULL, 
	email VARCHAR(190), 
	parent_email VARCHAR(190), 
	parent_phone VARCHAR(25), 
	created_at DATETIME NOT NULL DEFAULT now(), 
	PRIMARY KEY (id), 
	UNIQUE (user_id), 
	FOREIGN KEY(user_id) REFERENCES users (id) ON DELETE SET NULL, 
	FOREIGN KEY(class_id) REFERENCES classes (id) ON DELETE CASCADE, 
	UNIQUE (usn)
);

CREATE INDEX ix_students_class_id ON students (class_id);

CREATE TABLE subjects (
	id INTEGER NOT NULL AUTO_INCREMENT, 
	class_id INTEGER NOT NULL, 
	name VARCHAR(120) NOT NULL, 
	code VARCHAR(30) NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT uq_subject_class_code UNIQUE (class_id, code), 
	FOREIGN KEY(class_id) REFERENCES classes (id) ON DELETE CASCADE
);

CREATE INDEX ix_subjects_class_id ON subjects (class_id);

CREATE TABLE absence_reasons (
	id INTEGER NOT NULL AUTO_INCREMENT, 
	student_id INTEGER NOT NULL, 
	subject_id INTEGER, 
	date DATE NOT NULL, 
	category VARCHAR(30) NOT NULL, 
	reason TEXT NOT NULL, 
	proof_path VARCHAR(255), 
	status ENUM('pending','approved','rejected') NOT NULL, 
	reviewed_by INTEGER, 
	reviewed_at DATETIME, 
	review_note VARCHAR(255), 
	created_at DATETIME NOT NULL DEFAULT now(), 
	PRIMARY KEY (id), 
	FOREIGN KEY(student_id) REFERENCES students (id) ON DELETE CASCADE, 
	FOREIGN KEY(subject_id) REFERENCES subjects (id) ON DELETE SET NULL, 
	FOREIGN KEY(reviewed_by) REFERENCES users (id) ON DELETE SET NULL
);

CREATE INDEX ix_absence_reasons_student_id ON absence_reasons (student_id);

CREATE TABLE alerts (
	id INTEGER NOT NULL AUTO_INCREMENT, 
	student_id INTEGER NOT NULL, 
	subject_id INTEGER, 
	type VARCHAR(40) NOT NULL, 
	risk_score FLOAT NOT NULL, 
	level ENUM('low','medium','high','critical') NOT NULL, 
	explanation JSON NOT NULL, 
	status ENUM('open','dismissed','resolved') NOT NULL, 
	override_level ENUM('low','medium','high','critical'), 
	override_reason VARCHAR(255), 
	dismissed_by INTEGER, 
	dismissed_reason VARCHAR(255), 
	dismissed_score FLOAT, 
	created_at DATETIME NOT NULL DEFAULT now(), 
	updated_at DATETIME NOT NULL DEFAULT now(), 
	PRIMARY KEY (id), 
	FOREIGN KEY(student_id) REFERENCES students (id) ON DELETE CASCADE, 
	FOREIGN KEY(subject_id) REFERENCES subjects (id) ON DELETE CASCADE, 
	FOREIGN KEY(dismissed_by) REFERENCES users (id) ON DELETE SET NULL
);

CREATE INDEX ix_alert_student_status ON alerts (student_id, status);
CREATE INDEX ix_alerts_subject_id ON alerts (subject_id);
CREATE INDEX ix_alerts_status ON alerts (status);
CREATE INDEX ix_alerts_student_id ON alerts (student_id);

CREATE TABLE attendance (
	id INTEGER NOT NULL AUTO_INCREMENT, 
	student_id INTEGER NOT NULL, 
	subject_id INTEGER NOT NULL, 
	date DATE NOT NULL, 
	period INTEGER NOT NULL, 
	status ENUM('present','absent') NOT NULL, 
	marked_by INTEGER, 
	created_at DATETIME NOT NULL DEFAULT now(), 
	updated_at DATETIME NOT NULL DEFAULT now(), 
	PRIMARY KEY (id), 
	CONSTRAINT uq_attendance_slot UNIQUE (student_id, subject_id, date, period), 
	FOREIGN KEY(student_id) REFERENCES students (id) ON DELETE CASCADE, 
	FOREIGN KEY(subject_id) REFERENCES subjects (id) ON DELETE CASCADE, 
	FOREIGN KEY(marked_by) REFERENCES users (id) ON DELETE SET NULL
);

CREATE INDEX ix_attendance_student_id ON attendance (student_id);
CREATE INDEX ix_att_student_date ON attendance (student_id, date);
CREATE INDEX ix_attendance_subject_id ON attendance (subject_id);
CREATE INDEX ix_att_subject_date ON attendance (subject_id, date);

CREATE TABLE chatbot_logs (
	id INTEGER NOT NULL AUTO_INCREMENT, 
	student_id INTEGER NOT NULL, 
	question TEXT NOT NULL, 
	answer TEXT NOT NULL, 
	created_at DATETIME NOT NULL DEFAULT now(), 
	PRIMARY KEY (id), 
	FOREIGN KEY(student_id) REFERENCES students (id) ON DELETE CASCADE
);

CREATE INDEX ix_chatbot_logs_student_id ON chatbot_logs (student_id);

CREATE TABLE remarks (
	id INTEGER NOT NULL AUTO_INCREMENT, 
	student_id INTEGER NOT NULL, 
	author_id INTEGER NOT NULL, 
	`role` ENUM('mentor','teacher','student') NOT NULL, 
	text TEXT NOT NULL, 
	created_at DATETIME NOT NULL DEFAULT now(), 
	updated_at DATETIME NOT NULL DEFAULT now(), 
	PRIMARY KEY (id), 
	FOREIGN KEY(student_id) REFERENCES students (id) ON DELETE CASCADE, 
	FOREIGN KEY(author_id) REFERENCES users (id) ON DELETE CASCADE
);

CREATE INDEX ix_remarks_student_id ON remarks (student_id);

CREATE TABLE teacher_class_subject (
	id INTEGER NOT NULL AUTO_INCREMENT, 
	teacher_id INTEGER NOT NULL, 
	class_id INTEGER NOT NULL, 
	subject_id INTEGER NOT NULL, 
	assigned_by_mentor BOOL NOT NULL, 
	created_at DATETIME NOT NULL DEFAULT now(), 
	PRIMARY KEY (id), 
	CONSTRAINT uq_tcs UNIQUE (teacher_id, class_id, subject_id), 
	FOREIGN KEY(teacher_id) REFERENCES teachers (id) ON DELETE CASCADE, 
	FOREIGN KEY(class_id) REFERENCES classes (id) ON DELETE CASCADE, 
	FOREIGN KEY(subject_id) REFERENCES subjects (id) ON DELETE CASCADE
);

CREATE INDEX ix_teacher_class_subject_teacher_id ON teacher_class_subject (teacher_id);
CREATE INDEX ix_teacher_class_subject_subject_id ON teacher_class_subject (subject_id);
CREATE INDEX ix_teacher_class_subject_class_id ON teacher_class_subject (class_id);

CREATE TABLE attendance_audit_log (
	id INTEGER NOT NULL AUTO_INCREMENT, 
	attendance_id INTEGER, 
	student_id INTEGER NOT NULL, 
	subject_id INTEGER NOT NULL, 
	date DATE NOT NULL, 
	period INTEGER NOT NULL, 
	old_status VARCHAR(10), 
	new_status VARCHAR(10) NOT NULL, 
	changed_by INTEGER, 
	changed_at DATETIME NOT NULL DEFAULT now(), 
	reason VARCHAR(255), 
	PRIMARY KEY (id), 
	FOREIGN KEY(attendance_id) REFERENCES attendance (id) ON DELETE SET NULL, 
	FOREIGN KEY(student_id) REFERENCES students (id) ON DELETE CASCADE, 
	FOREIGN KEY(subject_id) REFERENCES subjects (id) ON DELETE CASCADE, 
	FOREIGN KEY(changed_by) REFERENCES users (id) ON DELETE SET NULL
);

CREATE INDEX ix_audit_student_date ON attendance_audit_log (student_id, date);

CREATE TABLE counselling_cases (
	id INTEGER NOT NULL AUTO_INCREMENT, 
	alert_id INTEGER NOT NULL, 
	student_id INTEGER NOT NULL, 
	message TEXT NOT NULL, 
	status ENUM('draft','sent','responded','escalated','resolved') NOT NULL, 
	thread_token VARCHAR(40) NOT NULL, 
	sent_at DATETIME, 
	deadline_at DATETIME, 
	responded_at DATETIME, 
	escalated_at DATETIME, 
	resolved_at DATETIME, 
	created_at DATETIME NOT NULL DEFAULT now(), 
	PRIMARY KEY (id), 
	FOREIGN KEY(alert_id) REFERENCES alerts (id) ON DELETE CASCADE, 
	FOREIGN KEY(student_id) REFERENCES students (id) ON DELETE CASCADE, 
	UNIQUE (thread_token)
);

CREATE INDEX ix_counselling_cases_status ON counselling_cases (status);
CREATE INDEX ix_counselling_cases_deadline_at ON counselling_cases (deadline_at);
CREATE INDEX ix_counselling_cases_alert_id ON counselling_cases (alert_id);
CREATE INDEX ix_counselling_cases_student_id ON counselling_cases (student_id);

CREATE TABLE interventions (
	id INTEGER NOT NULL AUTO_INCREMENT, 
	student_id INTEGER NOT NULL, 
	alert_id INTEGER, 
	staff_id INTEGER, 
	type VARCHAR(40) NOT NULL, 
	notes TEXT, 
	date DATE NOT NULL, 
	outcome VARCHAR(255), 
	attendance_before FLOAT, 
	attendance_after FLOAT, 
	created_at DATETIME NOT NULL DEFAULT now(), 
	PRIMARY KEY (id), 
	FOREIGN KEY(student_id) REFERENCES students (id) ON DELETE CASCADE, 
	FOREIGN KEY(alert_id) REFERENCES alerts (id) ON DELETE SET NULL, 
	FOREIGN KEY(staff_id) REFERENCES users (id) ON DELETE SET NULL
);

CREATE INDEX ix_interventions_student_id ON interventions (student_id);

CREATE TABLE counselling_messages (
	id INTEGER NOT NULL AUTO_INCREMENT, 
	case_id INTEGER NOT NULL, 
	sender VARCHAR(20) NOT NULL, 
	channel VARCHAR(10) NOT NULL, 
	body TEXT NOT NULL, 
	created_at DATETIME NOT NULL DEFAULT now(), 
	PRIMARY KEY (id), 
	FOREIGN KEY(case_id) REFERENCES counselling_cases (id) ON DELETE CASCADE
);

CREATE INDEX ix_counselling_messages_case_id ON counselling_messages (case_id);
